mapper.select:
SELECT pm.id, pm.position_id AS "positionId", pm.method_id AS "methodId",
       dm.method AS "methodName", pm.scope_kind AS "scopeKind", pm.scope_id AS "scopeId",
       pm.purpose, pm.allocation, pm.priority, pm.enabled
  FROM position_method pm
  JOIN device_method dm ON dm.id = pm.method_id
 WHERE pm.tenant_id = #{t} AND pm.position_id = #{positionId}
   AND pm.scope_kind = #{scopeKind}
   AND pm.scope_id = #{scopeId}
 ORDER BY pm.scope_kind, pm.priority, pm.id

SELECT id FROM workflow_node
 WHERE tenant_id = #{t} AND workflow_id = #{workflowId} AND node_key = #{nodeKey}
 ORDER BY id LIMIT 1
